import math
import sys


def digits_of_factorial(n):
    # n! has floor(log10 n!) + 1 digits; lgamma(n + 1) is ln n!
    if n <= 1:
        return 1
    return math.floor(math.lgamma(n + 1) / math.log(10)) + 1


for token in sys.stdin.read().split():
    print(digits_of_factorial(int(token)))

